INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "钱镠遣钱传瓘率军攻吴常州，徐温分兵抵御", "start_year": 919, "end_year": 919, "time_original": "919年七月；确日未载", "dynasty": "五代十国", "description": "钱镠遣钱传瓘率军攻吴常州，徐温分兵抵御。", "phases": [], "location_name": "常州、海门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a5d9ea6f-a82d-5998-8bf9-408138ece33a"}, {"title": "无锡交战时徐温病热，陈彦谦迁军旗稳住中军", "start_year": 919, "end_year": 919, "time_original": "919年七月壬申", "dynasty": "五代十国", "description": "无锡交战时徐温病热，陈彦谦迁军旗稳住中军。", "phases": [], "location_name": "无锡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0a8e393c-cefe-5681-b1e2-82e7f8a9cbec"}, {"title": "吴军乘风纵火大败吴越兵，钱传瓘遁走", "start_year": 919, "end_year": 919, "time_original": "919年七月壬申战后；追击确日未载", "dynasty": "五代十国", "description": "吴军乘风纵火大败吴越兵，钱传瓘遁走。", "phases": [], "location_name": "无锡、山南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "29597484-9ade-5ec6-932e-f082e9295a1f"}, {"title": "陈璋于香弯击败吴越军", "start_year": 919, "end_year": 919, "time_original": "919年七月无锡之战后本段；确日未载", "dynasty": "五代十国", "description": "陈璋于香弯击败吴越军。", "phases": [], "location_name": "香弯", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f7479077-73df-5d48-bffb-34f1845dee2e"}, {"title": "徐温悬赏生擒陈绍，崔彦章获之后仍用陈绍典兵", "start_year": 919, "end_year": 919, "time_original": "919年七月本段；确日未载", "dynasty": "五代十国", "description": "徐温悬赏生擒陈绍，崔彦章获之后仍用陈绍典兵。", "phases": [], "location_name": "吴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "db037035-7a38-5ceb-9b67-6e4588806dea"}, {"title": "曹筠此前奔吴越，徐温赦其家属并传话", "start_year": null, "end_year": null, "time_original": "锦衣之役；具体年未据本段确定", "dynasty": "五代十国", "description": "曹筠此前奔吴越，徐温赦其家属并传话。", "phases": [], "location_name": "吴、吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "054dfa6b-eec1-5b33-9c78-01e9d5e1642b"}, {"title": "曹筠在此役后复归吴，徐温不治罪并还其田宅官职", "start_year": 919, "end_year": 919, "time_original": "919年本段所承无锡之役后；卒日未载", "dynasty": "五代十国", "description": "曹筠在此役后复归吴，徐温不治罪并还其田宅官职。", "phases": [], "location_name": "吴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dbf01fe1-7cf9-50d7-a1d3-8b852a4682e1"}, {"title": "李昪请以两千步卒伪装吴越军袭苏州，徐温未采", "start_year": 919, "end_year": 919, "time_original": "919年无锡战后；确日未载", "dynasty": "五代十国", "description": "李昪请以两千步卒伪装吴越军袭苏州，徐温未采。", "phases": [], "location_name": "苏州、吴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6838dd20-b0fb-5ee1-bb3b-e0a4ab849abc"}, {"title": "徐温拒诸将乘胜灭吴越之议，引军还", "start_year": 919, "end_year": 919, "time_original": "919年无锡战后；确日未载", "dynasty": "五代十国", "description": "徐温拒诸将乘胜灭吴越之议，引军还。", "phases": [], "location_name": "吴越边境、吴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7dec7acf-81d1-50da-b503-ede0cd20bb83"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

